import { ApiKeys } from "@/components/api-keys";

<ApiKeys
  defaultValue={keys}
  scopes={[{ value: "read", label: "Read" }, { value: "write", label: "Write" }]}
  onCreate={async ({ name, scopes }) => {
    const res = await fetch("/api/keys", { method: "POST", body: JSON.stringify({ name, scopes }) });
    if (!res.ok) throw new Error((await res.json()).error);
    return res.json(); // { key, secret }
  }}
  onRevoke={(key) => fetch(`/api/keys/${key.id}`, { method: "DELETE" })}
/>
